sealed class SalaryHistory
{
    private readonly List<(DateOnly From, decimal Amount)> _byStart = new();   // sorted
    public decimal At(DateOnly when) {
        var i = _byStart.FindLastIndex(v => v.From <= when);   // latest start <= when
        if (i < 0) throw new KeyNotFoundException($"no salary effective on {when}");
        return _byStart[i].Amount;
    }
    public void Put(DateOnly from, decimal amount) {
        _byStart.RemoveAll(v => v.From == from); _byStart.Add((from, amount));
        _byStart.Sort((a, b) => a.From.CompareTo(b.From));
    }
}
